#include <Arduino.h>

const int LED = 2;   // the onboard LED on most ESP32 dev boards
int blinks = 0;

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
}

void loop() {
  digitalWrite(LED, HIGH);
  delay(500);
  digitalWrite(LED, LOW);
  delay(500);
  blinks++;
  Serial.printf("MIA BLINK %d\n", blinks);   // MIA reads this to check the lab
}
